const KEYS = { "/api/state": "state", "/api/work": "work" };
const MAX_BODY = 4_000_000;

const json = (body, status = 200) =>
  new Response(body, { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer" } });

const MAX_FAILS = 10, LOCK_SECONDS = 900;
function safeEq(a, b) {
  const x = new TextEncoder().encode(String(a)), y = new TextEncoder().encode(String(b));
  let d = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) d |= (x[i] || 0) ^ (y[i] || 0);
  return d === 0;
}
/* null when the request may proceed, otherwise the refusal to send */
async function gate(request, env) {
  if (!env.PASSPHRASE) return json('{"error":"PASSPHRASE secret is missing"}', 500);
  const ip = request.headers.get("CF-Connecting-IP") || "unknown";
  const lk = "lock:" + ip;
  let fails = 0;
  if (env.BRAIN_KV) { try { fails = parseInt(await env.BRAIN_KV.get(lk), 10) || 0; } catch (e) {} }
  if (fails >= MAX_FAILS) return json('{"error":"too many attempts, try again later"}', 429);
  if (safeEq(request.headers.get("Authorization") || "", "Bearer " + env.PASSPHRASE)) return null;
  if (env.BRAIN_KV) { try { await env.BRAIN_KV.put(lk, String(fails + 1), { expirationTtl: LOCK_SECONDS }); } catch (e) {} }
  return json('{"error":"unauthorised"}', 401);
}
