  const closes = {}, errors = {};
  await Promise.all(syms.map(s => monthCloses(s).then(m => { closes[s] = m; }, e => { errors[s] = String((e && e.message) || e).slice(0, 120); })));
  return json(JSON.stringify({ closes, errors }));
