export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const key = KEYS[url.pathname];

    if (url.pathname === "/add" || url.pathname === "/add/") return new Response(QUICK_HTML, { headers: PAGE_HEADERS });
    if (url.pathname === "/add/manifest.webmanifest") return new Response(QUICK_MANIFEST, { headers: { "Content-Type": "application/manifest+json", "Cache-Control": "public, max-age=86400", "X-Content-Type-Options": "nosniff" } });
    if (QUICK_ICONS[url.pathname]) return new Response(Uint8Array.from(atob(QUICK_ICONS[url.pathname]), ch => ch.charCodeAt(0)), { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=604800", "X-Content-Type-Options": "nosniff" } });
    if (url.pathname === "/api/spend" || url.pathname.startsWith("/api/spend/")) return handleSpend(request, env, url);
    if (url.pathname === "/api/qclose") {
      { const denied = await gate(request, env); if (denied) return denied; }
      if (request.method !== "GET") return json('{"error":"method not allowed"}', 405);
      return handleQClose(url);
    }

    if (url.pathname === "/api/seed") {
      { const denied = await gate(request, env); if (denied) return denied; }
      return json(JSON.stringify(PERSONAL_SEED));
    }

    if (url.pathname === "/api/finance-seed") {
      { const denied = await gate(request, env); if (denied) return denied; }
      return json(JSON.stringify(FIN_SEED));
    }

    if (url.pathname === "/api/quotes") {
      { const denied = await gate(request, env); if (denied) return denied; }
      if (request.method !== "GET") return json('{"error":"method not allowed"}', 405);
      return handleQuotes(url);
    }

    if (key) {
      if (!env.BRAIN_KV)   return json('{"error":"KV binding BRAIN_KV is missing"}', 500);
      { const denied = await gate(request, env); if (denied) return denied; }

      if (request.method === "GET") {
        const data = await env.BRAIN_KV.get(key);
        if (!data && key === "work") return json(WORK_DEFAULT);
        return json(data || "null");
      }

      if (request.method === "PUT") {
        const body = await request.text();
        if (body.length > MAX_BODY) return json('{"error":"payload too large"}', 413);
        let incoming;
        try { incoming = JSON.parse(body); } catch { return json('{"error":"invalid JSON"}', 400); }
        if (!incoming || typeof incoming !== "object" || Array.isArray(incoming)) return json('{"error":"expected an object"}', 400);

        const stored = await env.BRAIN_KV.get(key);
        if (stored) {
          let current = null;
          try { current = JSON.parse(stored); } catch {}
          const have = (current && current._rev) || 0;
          const got  = incoming._rev || 0;
          if (got <= have && have > 0) return json(stored, 409);
        }
        await env.BRAIN_KV.put(key, body);
        return json('{"ok":true,"_rev":' + (incoming._rev || 0) + '}');
      }

      return json('{"error":"method not allowed"}', 405);
    }

    return new Response(APP_HTML, { headers: PAGE_HEADERS });
  }
};